def find_paths(m: list[list[int]]) -> list[str]:
    n = len(m)
    if m[0][0] == 0 or m[n - 1][n - 1] == 0:
        return []
    paths = []
    visited = [[False] * n for _ in range(n)]
    dirs = [('D', 1, 0), ('L', 0, -1), ('R', 0, 1), ('U', -1, 0)]
    def dfs(r, c, curr):
        if r == n - 1 and c == n - 1:
            paths.append(curr)
            return
        visited[r][c] = True
        for d, dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n and not visited[nr][nc] and m[nr][nc] == 1:
                dfs(nr, nc, curr + d)
        visited[r][c] = False
    dfs(0, 0, '')
    return sorted(paths)
